# 复算对账容差：绝对 0.6 个百分点 与 相对 6% 取大者
_TOL_ABS_PCT = 0.6
_TOL_REL = 0.06

# 量纲护栏（单位：成交额=亿元，PE/PB=倍）
_TURNOVER_ABSURD_YI = 5000.0      # 单只个股单日成交额（亿元）超此视为疑似单位错误
