_ID_RE = re.compile(r"^[A-Za-z][A-Za-z0-9_.\-]*$")
_GROUP_ORDER = ("放量上攻", "缩量上行", "缩量回调", "放量杀跌")
_GROUP_UP = {"放量上攻", "缩量上行"}
